use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts named in this node's `HTTPClient<[...]>` scope. A request outside the
/// allowlist would trap at the boundary and fail the whole tick, so such URLs
/// are recorded as failures without being requested.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the lowercase host from an http(s) URL, or `None` if the URL is
/// not an http(s) URL with a recognisable host.
fn host_of(url: &str) -> Option<String> {
    let url = url.trim();
    let lower = url.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &url["https://".len()..]
    } else if lower.starts_with("http://") {
        &url["http://".len()..]
    } else {
        return None;
    };

    // Authority ends at the first '/', '?', '#' or '\\'.
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo; the real host follows the last '@'.
    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Bracketed (IPv6) literals are never on the allowlist.
    if hostport.starts_with('[') {
        return None;
    }

    // Drop a port.
    let host = match hostport.find(':') {
        Some(i) => &hostport[..i],
        None => hostport,
    };

    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's HTTP allowlist"),
                });
                continue;
            }

            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
